<?php use App\Core\Csrf; use App\Helpers\ViewHelper; $status = (string)$order['status']; $next = ['pending'=>'confirmed','confirmed'=>'shipping','shipping'=>'delivered']; ?>
<div class="section-heading"><div><p class="eyebrow">Bán hàng</p><h2>Chi tiết đơn hàng <?= ViewHelper::escape((string)$order['order_code']) ?></h2><p class="muted">Khách hàng: <?= ViewHelper::escape((string)$order['customer_name']) ?> · <?= ViewHelper::escape((string)$order['customer_email']) ?></p></div><a class="button" href="/admin/orders">Quay lại</a></div>
<?php if (!empty($error)): ?><div class="notice"><?= ViewHelper::escape($error) ?></div><?php endif; ?>
<section class="admin-detail-grid"><article class="admin-panel"><div class="section-heading"><div><p class="eyebrow">Trạng thái</p><h3><?= ViewHelper::escape(ViewHelper::orderStatus($status)) ?></h3></div><span class="report-badge report-badge-neutral"><?= ViewHelper::escape($order['created_at']) ?></span></div>
    <?php if (isset($next[$status])): ?><form method="post" action="/admin/orders/<?= (int)$order['id'] ?>/status" class="status-form"><?= Csrf::field() ?><input type="hidden" name="status" value="<?= $next[$status] ?>"><label for="status-reason">Ghi chú cập nhật</label><textarea id="status-reason" name="reason" rows="2" required></textarea><button class="button button-primary" type="submit">Chuyển sang <?= ViewHelper::escape(ViewHelper::orderStatus($next[$status])) ?></button></form><form method="post" action="/admin/orders/<?= (int)$order['id'] ?>/status" class="status-form"><?= Csrf::field() ?><input type="hidden" name="status" value="cancelled"><label for="admin-cancel-reason">Lý do hủy đơn</label><textarea id="admin-cancel-reason" name="reason" rows="2" required></textarea><button class="button button-danger" type="submit">Hủy đơn</button></form><?php endif; ?>
    <?php if ($status === 'cancel_requested'): ?><form method="post" action="/admin/orders/<?= (int)$order['id'] ?>/cancel-decision" class="status-form"><?= Csrf::field() ?><label for="cancel-decision-reason">Lý do xử lý yêu cầu hủy</label><textarea id="cancel-decision-reason" name="reason" rows="2" required></textarea><button class="button button-danger" name="decision" value="approve" type="submit">Chấp nhận hủy</button><button class="button" name="decision" value="reject" type="submit">Từ chối hủy</button></form><?php endif; ?>
    <?php if ($status === 'return_requested'): ?><form method="post" action="/admin/orders/<?= (int)$order['id'] ?>/return-decision" class="status-form"><?= Csrf::field() ?><p>Lý do khách: <?= ViewHelper::escape((string)$order['return_reason']) ?></p><?php if (!empty($order['return_image'])): ?><p><a href="/admin/orders/<?= (int)$order['id'] ?>/return-image" target="_blank">Xem hình ảnh đổi trả</a></p><?php endif; ?><label for="return-decision-reason">Ghi chú xử lý</label><textarea id="return-decision-reason" name="reason" rows="2" required></textarea><button class="button button-primary" name="decision" value="approve" type="submit">Đồng ý đổi trả</button><button class="button" name="decision" value="reject" type="submit">Từ chối đổi trả</button></form><?php endif; ?>
    <?php if ($status === 'return_shipping'): ?><form method="post" action="/admin/orders/<?= (int)$order['id'] ?>/return-received" class="status-form"><?= Csrf::field() ?><label for="return-received-reason">Ghi chú nhận hàng trả</label><textarea id="return-received-reason" name="reason" rows="2" required></textarea><button class="button button-primary" type="submit">Xác nhận đã nhận hàng trả</button></form><?php endif; ?>
    <?php if ($status === 'cancelled' && !empty($order['cancel_reason'])): ?><div class="notice">Lý do hủy: <?= ViewHelper::escape((string)$order['cancel_reason']) ?></div><?php endif; ?>
    <h3>Sản phẩm trong đơn</h3><ul class="order-products order-detail-products"><?php foreach ($order['items'] as $item): ?><li><span><?= ViewHelper::escape($item['book_title']) ?> × <?= (int)$item['quantity'] ?></span><strong><?= ViewHelper::money((int)$item['line_total']) ?></strong></li><?php endforeach; ?></ul><div class="order-total-row"><span>Tổng tiền</span><strong><?= ViewHelper::money((int)$order['total']) ?></strong></div>
</article><aside class="admin-panel"><h3>Thông tin giao hàng</h3><p><strong><?= ViewHelper::escape($order['shipping_name']) ?></strong><br><?= ViewHelper::escape($order['shipping_phone']) ?><br><?= ViewHelper::escape($order['shipping_email']) ?><br><?= ViewHelper::escape($order['shipping_address']) ?></p><h3>Thanh toán</h3><p><?= ViewHelper::escape(ViewHelper::paymentMethod((string)$order['payment_method'])) ?><br><?= ViewHelper::escape(ViewHelper::paymentStatus((string)$order['payment_status'])) ?></p><h3>Lịch sử</h3><ul class="order-timeline"><?php foreach ($order['history'] as $history): ?><li><strong><?= ViewHelper::escape(ViewHelper::orderStatus((string)$history['to_status'])) ?></strong><span><?= ViewHelper::escape((string)$history['note']) ?><br><?= ViewHelper::escape((string)$history['created_at']) ?></span></li><?php endforeach; ?></ul></aside></section>
